// Observe after the actual main-camera render, not the pre-render Editor update boundary.
using System;using System.IO;using System.Linq;using System.Collections.Generic;
using UnityEngine;using UnityEngine.Rendering;using UnityEditor;using Newtonsoft.Json;
public static class EnergyClusterRenderContinuity {
 static GameObject clone;static ParticleSystem[] systems;static bool background;static int frame=-1;static double begin;static List<object> rows=new List<object>();static int minimum=999;static EditorWindow focused;
 static void Done(){RenderPipelineManager.endCameraRendering-=Rendered;UnityEngine.Object.Destroy(clone);Application.runInBackground=background;if(focused!=null)focused.Focus();File.WriteAllText(Path.Combine(Directory.GetParent(Application.dataPath).FullName,"VFXWork/Previews/EnergyCluster/V6/RenderedContinuity.json"),JsonConvert.SerializeObject(new{method="Actual URP endCameraRendering / main camera only / no simulated frames",minimum,frames=rows.Count,rows},Formatting.Indented));}
 static void Rendered(ScriptableRenderContext context,Camera camera){if(camera!=Camera.main||frame==Time.frameCount)return;frame=Time.frameCount;int count=systems.Sum(p=>p.particleCount);if(Time.timeAsDouble-begin>.1)minimum=Math.Min(minimum,count);rows.Add(new{frame,count,clock=systems[0].time,age=Time.timeAsDouble-begin});if(Time.timeAsDouble-begin>5)Done();}
 public static string Run(){if(!Application.isPlaying||Application.productName!="VFXDemo")throw new Exception("Wrong scope/state");background=Application.runInBackground;Application.runInBackground=true;focused=EditorWindow.focusedWindow;EditorWindow.GetWindow(typeof(Editor).Assembly.GetType("UnityEditor.GameView")).Focus();clone=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/PixelFX/EnergyCluster/Prefabs/VFX_EnergyCluster_Loop.prefab"));clone.name="EnergyCluster_RenderContinuity_Temporary";systems=clone.GetComponentsInChildren<ParticleSystem>();begin=Time.timeAsDouble;RenderPipelineManager.endCameraRendering+=Rendered;return "After-render native continuity probe started (5 seconds engine time).";}
}
